const body = $input.first().json;
const vendors = body.vendors || (body.website ? [{ website: body.website, vendor_name: body.vendor_name || '', linkedin_url: body.linkedin_url || '' }] : []);
if (!vendors.length) throw new Error('vendors array required');
const rapidapi_key = (body.rapidapi_key || process.env.RAPIDAPI_KEY || '').trim();
if (!rapidapi_key) throw new Error('rapidapi_key required');
const admin_url = (body.admin_url || process.env.ADMIN_BASE_URL || 'http://127.0.0.1:8787').trim();
return vendors.map(v => ({ json: { website: v.website, vendor_name: v.vendor_name || '', linkedin_url: v.linkedin_url || '', rapidapi_key, admin_url } }));

const data = $input.first().json;
const website = $('Split Vendors').first().json.website;
const vendor_name = $('Split Vendors').first().json.vendor_name;

const company = data.data || data.company || data || {};
const extracted = {};

// Company LinkedIn URL
const linkedinUrl = company.linkedin_url || company.linkedInUrl || company.url;
if (linkedinUrl && linkedinUrl.includes('linkedin.com')) {
  extracted.linkedin_url = linkedinUrl;
}

// Extract executives / leadership
const employees = company.employees || company.executives || company.keyPeople || [];
const leadership = [];
let ceo_linkedin = '';
let ceo_name = '';

for (const person of employees) {
  const title = person.title || person.headline || '';
  const name = person.name || person.full_name || [person.firstName, person.lastName].filter(Boolean).join(' ');
  const profileUrl = person.linkedin_url || person.profile_url || person.url || '';
  if (name) {
    leadership.push({ name, title, linkedin_url: profileUrl });
    if (!ceo_name && /ceo|chief executive|founder|co.?founder/i.test(title)) {
      ceo_name = name;
      ceo_linkedin = profileUrl;
    }
  }
}

if (leadership.length) extracted.leadership = leadership;
if (ceo_name) extracted.ceo_name = ceo_name;
if (ceo_linkedin) extracted.ceo_linkedin = ceo_linkedin;

const has_data = Object.keys(extracted).length > 0;
return [{ json: { website, vendor_name, extracted, has_data, pipeline_name: 'csp-linkedin-enrichment' } }];
